From ef82bafe4694764a611bed1b415af7d1b71be7cb Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 18:57:13 +0100
Subject: [PATCH] Add a D-Bus method to insert text into the focused window

Clipboard managers had no way to paste a chosen entry into the window
they were opened from. insertText() commits text through text input, and
text sent just after a focus change waits for the client to catch up.

BUG: 427214
---
 src/dbusinterface.cpp |  8 ++++++++
 src/dbusinterface.h   |  8 ++++++++
 src/inputmethod.cpp   | 36 +++++++++++++++++++++++++++++++++++-
 src/inputmethod.h     |  7 +++++++
 src/org.kde.KWin.xml  |  4 ++++
 5 files changed, 62 insertions(+), 1 deletion(-)

diff --git a/src/dbusinterface.cpp b/src/dbusinterface.cpp
index 6110ddfe64..89f8fed8db 100644
--- a/src/dbusinterface.cpp
+++ b/src/dbusinterface.cpp
@@ -18,6 +18,7 @@
 #include "core/output.h"
 #include "core/renderbackend.h"
 #include "debug_console.h"
+#include "inputmethod.h"
 #include "kwinadaptor.h"
 #include "main.h"
 #include "placement.h"
@@ -187,6 +188,13 @@ QVariantMap DBusInterface::getWindowInfo(const QString &uuid)
     }
 }

+void DBusInterface::insertText(const QString &text)
+{
+    if (auto inputMethod = kwinApp()->inputMethod(); inputMethod && !text.isEmpty()) {
+        inputMethod->sendText(text);
+    }
+}
+
 void DBusInterface::showDesktop(bool show)
 {
     workspace()->setShowingDesktop(show, true);
diff --git a/src/dbusinterface.h b/src/dbusinterface.h
index ebabdef1bc..f7757691e7 100644
--- a/src/dbusinterface.h
+++ b/src/dbusinterface.h
@@ -88,6 +88,14 @@ public Q_SLOTS: // METHODS

     Q_NOREPLY void showDesktop(bool show);

+    /**
+     * Inserts @p text into the focused window, as if it had been typed.
+     *
+     * The text is committed through the text input protocol if the window supports it,
+     * otherwise it is typed with key events.
+     */
+    Q_NOREPLY void insertText(const QString &text);
+
 Q_SIGNALS:
     void showingDesktopChanged(bool showing);

diff --git a/src/inputmethod.cpp b/src/inputmethod.cpp
index ee7153b2db..22b8c1bec9 100644
--- a/src/inputmethod.cpp
+++ b/src/inputmethod.cpp
@@ -54,6 +54,8 @@
 #include <unistd.h>
 #include <xkbcommon/xkbcommon-keysyms.h>

+using namespace std::chrono_literals;
+
 namespace KWin
 {

@@ -93,6 +95,14 @@ void InputMethod::init()
     connect(&m_inputMethodCrashTimer, &QTimer::timeout, this, [this] {
         m_inputMethodCrashes = 0;
     });
+
+    m_waitingTextTimer.setSingleShot(true);
+    connect(&m_waitingTextTimer, &QTimer::timeout, this, [this] {
+        m_textInputStateUpdated = true;
+        if (!m_waitingText.isEmpty()) {
+            commitString(m_serial++, std::exchange(m_waitingText, QString()));
+        }
+    });
 #if KWIN_BUILD_SCREENLOCKER
     connect(ScreenLocker::KSldApp::self(), &ScreenLocker::KSldApp::aboutToLock, this, &InputMethod::hide);
 #endif
@@ -353,6 +363,8 @@ void InputMethod::handleFocusedSurfaceChanged()
         || seat->textInputV3()->clientSupportsTextInput(client)
         || m_internalContext->isEnabled();

+    m_textInputStateUpdated = !ret;
+
     if (ret != m_activeClientSupportsTextInput) {
         m_activeClientSupportsTextInput = ret;
         Q_EMIT activeClientSupportsTextInputChanged();
@@ -401,6 +413,10 @@ void InputMethod::contentTypeChanged()

 void InputMethod::textInputInterfaceV2StateUpdated(quint32 serial, TextInputV2Interface::UpdateReason reason)
 {
+    if (reason == TextInputV2Interface::UpdateReason::StateEnter || reason == TextInputV2Interface::UpdateReason::StateFull) {
+        textInputStateUpdated();
+    }
+
     auto t2 = waylandServer()->seat()->textInputV2();
     auto inputContext = waylandServer()->inputMethod()->context();
     if (!inputContext) {
@@ -434,6 +450,9 @@ void InputMethod::textInputInterfaceV3EnabledChanged()
 {
     auto t3 = waylandServer()->seat()->textInputV3();
     refreshActive();
+    if (t3->isEnabled()) {
+        textInputStateUpdated();
+    }
     if (t3->isEnabled() && t3->implicitShowPanelRequired()) {
         show();
     } else {
@@ -515,7 +534,22 @@ void InputMethod::keysymReceived(quint32 serial, quint32 time, quint32 sym, Keyb

 void InputMethod::sendText(const QString &text)
 {
-    commitString(m_serial++, text);
+    if (m_textInputStateUpdated) {
+        commitString(m_serial++, text);
+        return;
+    }
+    m_waitingText += text;
+    if (!m_waitingTextTimer.isActive()) {
+        m_waitingTextTimer.start(500ms);
+    }
+}
+
+void InputMethod::textInputStateUpdated()
+{
+    m_textInputStateUpdated = true;
+    if (!m_waitingText.isEmpty()) {
+        m_waitingTextTimer.start(0ms);
+    }
 }

 void InputMethod::commitString(quint32 serial, const QString &text)
diff --git a/src/inputmethod.h b/src/inputmethod.h
index 8398e1477c..c05b09a7d5 100644
--- a/src/inputmethod.h
+++ b/src/inputmethod.h
@@ -284,6 +284,7 @@ private:
     void refreshActive();
     void forwardKeyToEffects(KWin::KeyboardKeyState state, int keyCode, int keySym);
     void forwardKeySym(int keySym);
+    void textInputStateUpdated();

     // buffered till the preedit text is set
     struct
@@ -296,6 +297,12 @@ private:
     // TextInputV3 does not have a flag for this, so we have to handle it in the compositor
     QString m_pendingText = QString();

+    // A client that just got focus drops text committed before it has caught up with the
+    // focus change, so text from sendText() waits until it updates its text input state
+    QString m_waitingText;
+    QTimer m_waitingTextTimer;
+    bool m_textInputStateUpdated = true;
+
     VirtualKeyboardVisibility m_virtualKeyboardVisibility = VirtualKeyboardVisibility::NonMouseInput;
     quint32 m_serial = 0;
     QPointer<InputPanelV1Window> m_panel;
diff --git a/src/org.kde.KWin.xml b/src/org.kde.KWin.xml
index b073a71cd5..f992605419 100644
--- a/src/org.kde.KWin.xml
+++ b/src/org.kde.KWin.xml
@@ -41,6 +41,10 @@
         <annotation name="org.freedesktop.DBus.Method.NoReply" value="true"/>
         <arg name="showing" type="b" direction="in"/>
     </method>
+    <method name="insertText">
+        <annotation name="org.freedesktop.DBus.Method.NoReply" value="true"/>
+        <arg name="text" type="s" direction="in"/>
+    </method>
     <signal name="showingDesktopChanged">
         <arg name="showing" type="b" direction="out"/>
     </signal>
