From 8f1401a445c72e4bc6831059dd0bd91b08105476 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 18:57:22 +0100
Subject: [PATCH] klipper: optionally paste the selected entry into the active
 window

Choosing an entry only put it on the clipboard, so it still had to be
pasted by hand. A new option inserts text entries into the window that
gets the focus back once the popup closes, through KWin's insertText().

BUG: 427214
---
 applets/clipboard/qml/main.qml                |  7 ++-
 klipper/configdialog.cpp                      |  9 ++++
 klipper/configdialog.h                        |  1 +
 .../declarative/declarativehistorymodel.cpp   |  5 +++
 klipper/declarative/declarativehistorymodel.h |  1 +
 klipper/declarative/qml/KlipperPopup.qml      |  5 ++-
 klipper/klipper.cpp                           | 45 ++++++++++++++++++-
 klipper/klipper.h                             |  6 +++
 klipper/klipper.kcfg                          |  5 +++
 9 files changed, 80 insertions(+), 4 deletions(-)

diff --git a/applets/clipboard/qml/main.qml b/applets/clipboard/qml/main.qml
index 101b18486a..a8b1a4fcf9 100644
--- a/applets/clipboard/qml/main.qml
+++ b/applets/clipboard/qml/main.qml
@@ -163,8 +163,11 @@ PlasmoidItem {
                 barcodeType: Plasmoid.configuration.barcodeType
                 showHeader: Plasmoid.containment.pluginName !== "org.kde.plasma.systemtray"

-                onItemSelected: if (main.hideOnWindowDeactivate) {
-                    main.expanded = false;
+                onItemSelected: uuid => {
+                    if (main.hideOnWindowDeactivate) {
+                        historyModel.pasteIntoActiveWindow(uuid);
+                        main.expanded = false;
+                    }
                 }
                 onConfigureClicked: configureAction.trigger()
             }
