@@ -92,6 +93,14 @@ GeneralWidget::GeneralWidget(QWidget *parent)
     KLocalization::setupSpinBoxFormatString(m_historySizeSb, ki18ncp("Number of entries", "%v entry", "%v entries"));
     layout->addRow(item->label(), m_historySizeSb);

