 }

+void Klipper::pasteIntoActiveWindow(const QString &uuid)
+{
+    auto waylandApp = qGuiApp->nativeInterface<QNativeInterface::QWaylandApplication>();
+    QWindow *popup = qGuiApp->focusWindow();
+    if (!KlipperSettings::pasteSelectedItem() || !waylandApp || !popup) {
+        return;
+    }
+    const QModelIndex index = m_historyModel->index(m_historyModel->indexOf(uuid));
+    if (!index.isValid() || index.data(HistoryModel::TypeRole).value<HistoryItemType>() != HistoryItemType::Text) {
+        return;
+    }
+
+    // The text is for the window that gets the keyboard focus back once the popup is gone, so wait
+    // for the popup to be hidden and for the compositor to have handled it before sending the text
+    connect(
+        popup,
+        &QWindow::visibleChanged,
+        this,
+        [waylandApp, text = index.data(Qt::DisplayRole).toString()](bool visible) {
+            if (visible) {
+                return;
+            }
+            static const wl_callback_listener listener{
+                .done =
+                    [](void *data, wl_callback *callback, uint32_t) {
+                        auto text = static_cast<QString *>(data);
+                        QDBusMessage message = QDBusMessage::createMethodCall(u"org.kde.KWin"_s, u"/KWin"_s, u"org.kde.KWin"_s, u"insertText"_s);
+                        message << *text;
+                        QDBusConnection::sessionBus().send(message);
+                        delete text;
+                        wl_callback_destroy(callback);
+                    },
+            };
+            wl_callback_add_listener(wl_display_sync(waylandApp->display()), &listener, new QString(text));
+            wl_display_flush(waylandApp->display());
+        },
+        Qt::SingleShotConnection);
+}
+
 #include "moc_klipper.cpp"
diff --git a/klipper/klipper.h b/klipper/klipper.h
index 712ee8fce8..af67d52938 100644
--- a/klipper/klipper.h
