     KlipperPopup *popup();

+    /**
+     * Inserts the text item @p uuid into the window that gets the keyboard focus once the
+     * clipboard popup is closed, if the user enabled it.
+     */
+    void pasteIntoActiveWindow(const QString &uuid);
+
 public Q_SLOTS:
     void saveSession();
     void slotConfigure();
diff --git a/klipper/klipper.kcfg b/klipper/klipper.kcfg
index 088d17f5de..be092f8e89 100644
--- a/klipper/klipper.kcfg
+++ b/klipper/klipper.kcfg
@@ -34,6 +34,11 @@
       <default>false</default>
       <whatsthis>Store images in the clipboard history.</whatsthis>
     </entry>
+    <entry name="PasteSelectedItem" type="Bool">
+      <label>Paste the selected entry into the active window</label>
+      <default>false</default>
+      <whatsthis>When a text entry is chosen from the clipboard history, it is also inserted at the cursor of the window that was active before the clipboard popup opened.</whatsthis>
+    </entry>
     <entry name="URLGrabberEnabled" type="Bool">
